# inspect component bounds as extracted using analogous code
h,w=len(test_grid),len(test_grid[0]); seen=set(); comps=[]
for r in range(h):
 for c in range(w):
  if test_grid[r][c]==0 or (r,c) in seen: continue
  st=[(r,c)]; seen.add((r,c)); cells=[]
  while st:
   y,x=st.pop(); cells.append((y,x))
   for dy in (-1,0,1):
    for dx in (-1,0,1):
     ny,nx=y+dy,x+dx
     if (dy or dx) and 0<=ny<h and 0<=nx<w and test_grid[ny][nx] and (ny,nx) not in seen: seen.add((ny,nx)); st.append((ny,nx))
  comps.append((min(y for y,x in cells),max(y for y,x in cells),min(x for y,x in cells),max(x for y,x in cells),len(cells)))
comps
